38	// 此时亏损 0 未触线、金额合计恰满，两项限额都允许保留该部分成交买单。
39	func riskAmountGapSetup(t *testing.T) (e *Engine, bPartial int64) {
40		t.Helper()
41		e, _ = NewEngine(1000)
42		mustSetMax(t, e, "A", 100)
43		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
44		b0 := mustBuy(t, e, "A", 10, 10)
45		if _, err := e.Fill(Trade{TradeID: 1, OrderID: b0, Symbol: "A", Side: Buy, Price: 10, Qty: 10}); err != nil {
46			t.Fatal(err)
47		}
48		if err := e.StartTradingDay(1, 50); err != nil {
49			t.Fatal(err)
50		}
51		bPartial = mustBuy(t, e, "A", 20, 8)
52		if _, err := e.Fill(Trade{TradeID: 2, OrderID: bPartial, Symbol: "A", Side: Buy, Price: 8, Qty: 2}); err != nil {
53			t.Fatal(err)
54		}
55		if _, err := e.SetPositionAmountLimit(300); err != nil {
