66		}
67		am := e.PositionAmountStatus()
68		if !am.Enabled || am.Limit != 300 || am.Holding != 120 || am.BuyReserved != 180 || am.Total != 300 {
69			t.Fatalf("提交前金额状态必须恰好允许保留该买单: %+v", am)
70		}
