72	}
73	
74	// TestRiskAmountGapFillLossCanceledBuyExcludedFromLaterQuote 覆盖成功路径：
75	// seq3@5 使亏损 56 达到上限 50（链中触线，撤销买单剩余 18 股）；seq4 大幅
76	// 回升，12×p4 与现金加持仓净值都可表示，但 18×p4 必然溢出。若实现错误地把
77	// 已撤剩余量计入 seq4 的金额计算，整批会被误判溢出而回滚；正确实现必须成功。
78	func TestRiskAmountGapFillLossCanceledBuyExcludedFromLaterQuote(t *testing.T) {
79		e, bPartial := riskAmountGapSetup(t)
80	
81		// p4 = MaxInt64/18 + 1：已撤的 18 股若被计入则 18×p4 溢出；
82		// 真实持仓 12×p4 与净值 884+12×p4 都可表示。
