90		// 后续序号先到并等待：seq3 触线价、seq4 回升价。
91		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 5}, 0)
92		mustQuote(t, e, "A", Quote{Seq: 4, Moment: 4, Price: p4}, 0)
93		if !e.HasGap("A") {
94			t.Fatal("seq3/seq4 跨号必须进入等待")
95		}
96	
97		// 等待中的报价不得提前改变风险状态、金额状态、订单与占用。
98		if st := e.RiskStatus(); st.Restricted || st.Equity != 1004 || st.Loss != 0 {
99			t.Fatalf("等待报价不得提前参与估值或触线: %+v", st)
100		}
101		if am := e.PositionAmountStatus(); am.Holding != 120 || am.BuyReserved != 180 || am.Total != 300 {
102			t.Fatalf("等待报价不得提前参与金额计算: %+v", am)
103		}
104		if o, _ := e.Order(bPartial); o.Status != StatusPartial || o.Remaining() != 18 {
105			t.Fatalf("等待期间不得提前撤单: %+v", o)
106		}
107		if e.ReservedCash() != 144 {
108			t.Fatalf("等待期间现金占用不得变化: %d", e.ReservedCash())
109		}
110	
111		// 补齐缺失的 seq2@9：链为 seq2@9（亏损 8，不触线）→ seq3@5（亏损 56，
112		// 触线撤单）→ seq4@p4（回升，亏损归零），三条全部生效。
113		recsBefore := len(e.Records())
114		n, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 2, Price: 9})
