120		}
121	
122		// 即使批末回升，日内限制必须保留；净值按末条报价计算、亏损归零。
123		st := e.RiskStatus()
124		if !st.Open || st.Day != 1 || st.Baseline != 1000 || st.LossLimit != 50 {
