147		}
148		if e.Cash() != 884 || e.Position("A") != 12 {
149			t.Fatalf("已成交入账的现金与持仓不得变化: cash=%d pos=%d", e.Cash(), e.Position("A"))
150		}
151	
152		// 最新报价推进到末条，缺口消失。
153		q, ok := e.CurrentQuote("A")
154		if !ok || q.Seq != 4 || q.Price != p4 {
155			t.Fatalf("最新报价应推进到末条 seq4@p4: %+v ok=%v", q, ok)
156		}
157		if e.HasGap("A") {
158			t.Fatal("链全部生效后不得再报告缺口")
159		}
160	
161		// 金额查询按末条报价计算真实持仓：Holding=12×p4，买单占用为零。
162		// 不能为避开溢出漏算持仓（Holding=0），也不能沿用触线时的低价（12×5=60）。
163		am := e.PositionAmountStatus()
164		if !am.Enabled || am.Limit != 300 {
165			t.Fatalf("金额上限设置应保持: %+v", am)
166		}
167		if am.Holding != wantHolding || am.BuyReserved != 0 || am.Total != wantHolding {
168			t.Fatalf("末条报价下应只剩真实持仓市值、买单占用为零: %+v want holding=%d", am, wantHolding)
169		}
170	
171		// 本批只新增“当日首次触线 + 实际撤单”共 2 条记录，无任何拒绝记录。
172		recs := e.Records()
173		newRecs := recs[recsBefore:]
174		if len(newRecs) != 2 {
175			t.Fatalf("应只新增 2 条记录（1 触线 + 1 撤单），实际 %d 条", len(newRecs))
176		}
177		trig := newRecs[0]
178		if trig.Kind != RecordRiskTriggered {
179			t.Fatalf("第一条新增记录必须是触线记录: %+v", trig)
180		}
181		if trig.RiskTrigger != RiskTriggerQuote || trig.RiskRefSeq != 3 || trig.RiskRefMoment != 3 {
182			t.Fatalf("触线来源与报价定位必须固化在真正触线的 seq3@时刻3: trigger=%s ref=%d moment=%d",
183				trig.RiskTrigger, trig.RiskRefSeq, trig.RiskRefMoment)
184		}
185		if trig.RiskDay != 1 || trig.RiskBaseline != 1000 || trig.RiskEquity != 944 ||
186			trig.RiskLoss != 56 || trig.RiskLimit != 50 || !trig.RiskRestrict {
187			t.Fatalf("触线快照必须固化中间价下的亏损: %+v", trig)
188		}
189		if len(trig.RiskQuoteRefs) != 1 ||
190			trig.RiskQuoteRefs[0] != (RiskQuoteRef{Symbol: "A", Seq: 3, Moment: 3, Price: 5}) {
191			t.Fatalf("参与估值的报价定位必须锚定 seq3@5: %+v", trig.RiskQuoteRefs)
192		}
193	
194		cr := newRecs[1]
195		if cr.Kind != RecordCanceled || cr.OrderID != bPartial || cr.Filled != 2 || cr.Remaining != 18 {
196			t.Fatalf("撤单记录必须标明取消剩余 18 股、已成交 2 股: %+v", cr)
197		}
198		if !strings.Contains(cr.Reason, "日内亏损 56") {
199			t.Fatalf("撤单记录原因必须来自日内亏损保护: %q", cr.Reason)
200		}
201		if cr.QuoteSeq != 3 || cr.QuotePrice != 5 || cr.QuoteMoment != 3 {
202			t.Fatalf("撤单报价快照应锚定触线时的 seq3@5: %+v", cr)
203		}
204		if cr.RiskDay != 1 || cr.RiskEquity != 944 || cr.RiskLoss != 56 ||
205			cr.RiskLimit != 50 || !cr.RiskRestrict {
206			t.Fatalf("撤单记录应携带触线时风险快照: %+v", cr)
207		}
208		if cr.AmtEnabled {
209			t.Fatalf("撤单由亏损保护引发，不得记为金额上限撤单: %+v", cr)
210		}
211		for _, r := range newRecs {
212			if r.Kind == RecordRejected {
213				t.Fatalf("成功补齐不得新增金额溢出等拒绝记录: %+v", r)
214			}
215		}
216		if countRiskRecords(e) != 1 {
217			t.Fatal("一个交易日只能有一条触线记录")
218		}
219	
220		// 限制保留：新买单继续被拒（与本批事件记录无关，放在记录断言之后）。
221		if _, err := e.Buy("A", 1, 1); err == nil {
222			t.Fatal("限制保留期间新买单必须拒绝")
223		}
224	}
225	
226	// TestRiskAmountGapFillLaterHoldingOverflowRollsBack 覆盖边界之一：链中 seq3@5
227	// 本会触线撤单，但链末 seq4 使仍保留的持仓市值 12×p4 超出 int64。撤单排除
228	// 规则不得扩大为忽略持仓——整批必须回滚：0 条生效、不触线、不撤单，订单、
229	// 资金占用与日内限制保持提交前状态，等待报价继续等待，只新增一条拒绝记录。
230	func TestRiskAmountGapFillLaterHoldingOverflowRollsBack(t *testing.T) {
231		e, bPartial := riskAmountGapSetup(t)
232	
233		p4 := int64(math.MaxInt64 / 8) // 12×p4 必然溢出 int64
234		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 5}, 0)
235		mustQuote(t, e, "A", Quote{Seq: 4, Moment: 4, Price: p4}, 0)
236	
237		recsBefore := len(e.Records())
238		n, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 2, Price: 9})
239		if !errors.Is(err, ErrInt64Overflow) {
240			t.Fatalf("链末持仓市值溢出必须返回包装 ErrInt64Overflow 的错误，实际 %v", err)
241		}
242		if n != 0 {
243			t.Fatalf("整批失败时生效条数必须为零，实际 %d", n)
244		}
245	
246		// 最新报价、开日基准、亏损上限与未限制状态全部保留。
247		q, _ := e.CurrentQuote("A")
248		if q.Seq != 1 || q.Price != 10 {
249			t.Fatalf("回滚后最新报价应停留在 seq1@10: %+v", q)
250		}
251		st := e.RiskStatus()
252		if !st.Open || st.Day != 1 || st.Baseline != 1000 || st.LossLimit != 50 {
253			t.Fatalf("开日状态必须保留: %+v", st)
254		}
255		if st.Restricted || st.Equity != 1004 || st.Loss != 0 {
256			t.Fatalf("拟触发的触线不得留下，净值保持提交前估值: %+v", st)
257		}
258	
259		// 链中本拟触发的撤单不得改变订单、资金占用与持仓。
260		if o, _ := e.Order(bPartial); o.Status != StatusPartial || o.Filled != 2 || o.Remaining() != 18 {
261			t.Fatalf("部分成交买单必须保持提交前状态: %+v", o)
262		}
263		if e.ReservedCash() != 144 || e.Cash() != 884 || e.Position("A") != 12 {
264			t.Fatalf("回滚后资金与占用必须保持提交前值: reserved=%d cash=%d pos=%d",
265				e.ReservedCash(), e.Cash(), e.Position("A"))
266		}
267		if am := e.PositionAmountStatus(); am.Holding != 120 || am.BuyReserved != 180 || am.Total != 300 {
268			t.Fatalf("回滚后金额状态应恢复提交前值: %+v", am)
269		}
270	
271		// 原先等待的 seq3/seq4 仍然等待，不能被当作已处理报价丢弃。
272		if !e.HasGap("A") {
273			t.Fatal("回滚后等待中的报价必须继续等待")
274		}
275	
276		// 只新增一条说明估值溢出的拒绝记录，不得留下触线或撤单记录。
277		recs := e.Records()
278		if len(recs) != recsBefore+1 {
279			t.Fatalf("整批失败只能新增一条记录，实际 %d 条", len(recs)-recsBefore)
280		}
281		rj := recs[recsBefore]
282		if rj.Kind != RecordRejected {
283			t.Fatalf("唯一新增记录必须是拒绝记录: %+v", rj)
284		}
285		if !strings.Contains(rj.Reason, "序号 4") || !strings.Contains(rj.Reason, "int64") {
286			t.Fatalf("拒绝原因必须指明链中无法估值的 seq4 与 int64 溢出: %q", rj.Reason)
287		}
288		if rj.QuoteSeq != 1 || rj.QuotePrice != 10 {
289			t.Fatalf("拒绝记录的报价快照应停留在 seq1@10: %+v", rj)
290		}
291		if rj.RiskDay != 1 || rj.RiskEquity != 1004 || rj.RiskLoss != 0 || rj.RiskRestrict {
292			t.Fatalf("拒绝记录应携带提交前的风险快照: %+v", rj)
293		}
294		for _, r := range recs[recsBefore:] {
295			if r.Kind == RecordRiskTriggered || r.Kind == RecordCanceled {
296				t.Fatalf("失败提交不得留下触线或撤单记录: %+v", r)
297			}
298		}
299		if countRiskRecords(e) != 0 {
300			t.Fatal("整批失败后不得存在任何触线记录")
301		}
302	
303		// 等待报价同内容重复提交仍是无操作；再次补齐会重新组链并因同一溢出失败。
304		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 5}, 0)
305		mustQuote(t, e, "A", Quote{Seq: 4, Moment: 4, Price: p4}, 0)
306		if n2, err2 := e.UpdateQuote("A", Quote{Seq: 2, Moment: 2, Price: 9}); !errors.Is(err2, ErrInt64Overflow) || n2 != 0 {
307			t.Fatalf("等待报价保留时，重新补齐必须仍可识别同一溢出: n=%d err=%v", n2, err2)
308		}
309	}
310	
311	// TestRiskAmountGapFillLaterEquityOverflowRollsBack 覆盖边界之二：链末报价下
312	// 持仓市值 12×p4 本身仍可用 int64 表示，但现金余额加持仓市值的净值溢出。
313	// 这同样必须识别为估值溢出并整批回滚，且不得把撤单排除规则扩大为忽略持仓。
314	func TestRiskAmountGapFillLaterEquityOverflowRollsBack(t *testing.T) {
315		e, bPartial := riskAmountGapSetup(t)
316	
317		p4 := int64(math.MaxInt64 / 12) // 12×p4 可表示，884+12×p4 溢出
318		if 12*p4 > math.MaxInt64 {
319			t.Fatal("测试构造错误：12×p4 必须可表示")
320		}
321		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 5}, 0)
322		mustQuote(t, e, "A", Quote{Seq: 4, Moment: 4, Price: p4}, 0)
323	
324		recsBefore := len(e.Records())
325		n, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 2, Price: 9})
326		if !errors.Is(err, ErrInt64Overflow) || n != 0 {
327			t.Fatalf("现金加持仓净值溢出必须整批失败且 0 条生效: n=%d err=%v", n, err)
328		}
329	
330		// 报价、订单、资金占用、金额状态与日内限制全部保持提交前状态。
331		q, _ := e.CurrentQuote("A")
332		if q.Seq != 1 || q.Price != 10 || !e.HasGap("A") {
333			t.Fatalf("回滚后最新报价停留 seq1 且 seq3/seq4 继续等待: q=%+v gap=%v", q, e.HasGap("A"))
334		}
335		st := e.RiskStatus()
336		if st.Restricted || st.Equity != 1004 || st.Loss != 0 || st.Baseline != 1000 || st.LossLimit != 50 {
337			t.Fatalf("拟触线不得留下，风险状态保持提交前: %+v", st)
338		}
339		if o, _ := e.Order(bPartial); o.Status != StatusPartial || o.Filled != 2 || o.Remaining() != 18 {
340			t.Fatalf("部分成交买单必须保持提交前状态: %+v", o)
341		}
342		if e.ReservedCash() != 144 || e.Cash() != 884 || e.Position("A") != 12 {
343			t.Fatalf("资金与占用必须保持提交前值: reserved=%d cash=%d pos=%d",
344				e.ReservedCash(), e.Cash(), e.Position("A"))
345		}
346		if am := e.PositionAmountStatus(); am.Holding != 120 || am.BuyReserved != 180 || am.Total != 300 {
347			t.Fatalf("金额状态应恢复提交前值: %+v", am)
348		}
349	
350		// 只新增一条说明估值溢出的拒绝记录，不得留下触线或撤单记录。
351		recs := e.Records()
352		if len(recs) != recsBefore+1 || recs[recsBefore].Kind != RecordRejected {
353			t.Fatalf("只能新增一条拒绝记录，实际 %d 条", len(recs)-recsBefore)
354		}
355		rj := recs[recsBefore]
356		if !strings.Contains(rj.Reason, "序号 4") || !strings.Contains(rj.Reason, "int64") {
357			t.Fatalf("拒绝原因必须指明 seq4 的 int64 估值溢出: %q", rj.Reason)
358		}
359		for _, r := range recs[recsBefore:] {
360			if r.Kind == RecordRiskTriggered || r.Kind == RecordCanceled {
361				t.Fatalf("失败提交不得留下触线或撤单记录: %+v", r)
362			}
363		}
364		if countRiskRecords(e) != 0 {
365			t.Fatal("整批失败后不得存在触线记录")
366		}
367	}
