		t.Fatalf("UpdateQuote(%+v) 意外错误: %v", q, err)
	}
	if n != wantApplied {
		t.Fatalf("UpdateQuote(seq=%d) 生效条数=%d, 期望 %d", q.Seq, n, wantApplied)
	}
}

func mustSetMax(t *testing.T, e *Engine, symbol string, max int64) []int64 {
	t.Helper()
	ids, err := e.SetMaxPosition(symbol, max)
