		t.Fatalf("等待报价不得推进最新报价: q=%+v gap=%v", q, e.HasGap("A"))
	}

	// 完全相同的 seq3 重复提交：仍成功返回 0。
	mustQuote(t, e, "A", Quote{Seq: 3, Moment: 30, Price: 20}, 0)

